from taf.gnb.oam.coam.cu.services.internal.trs.http_client_v1 import TRSv1HttpClient
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh()
class TRSv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = TRSv1HttpClient(base_url=con_details.base_url,
                                            connection_alias=con_details.alias)

    def get_trs_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_trs_operation_status(operation_id=operation_id, timeout=timeout)

    def start_ip_connectivity_test(self, destination_ip, payload_size, dscp, source_interface_name, source_ip=None):
        ping_test_setup = {"name": source_interface_name,
                           "sourceIp": source_ip,
                           "destinationIp": destination_ip,
                           "payloadSize": payload_size,
                           "dscp": dscp}
        return self.local_client.start_ip_connectivity_test(ping_test_setup=ping_test_setup)

    def get_ip_connectivity_test_result(self, operation_id):
        return self.local_client.get_ip_connectivity_test_result(operation_id=operation_id)

    def update_uplane_configuration(self, ip_address, port, dscp, timeout):
        return self.local_client.update_uplane_configuration(ip_address=ip_address,
                                                             port=port,
                                                             dscp=dscp,
                                                             timeout=timeout)

    def get_uplane_configuration(self, timeout):
        return self.local_client.get_uplane_configuration(timeout=timeout)

    def update_cu_psk_configuration(self, password, timeout=30):
        return self.local_client.update_cu_psk_configuration(password=password, timeout=timeout)

    def start_pmtu_discovery(self, name, source_ip, destination_ip, dscp, timeout=30):
        return self.local_client.start_pmtu_discovery(name=name,
                                                      source_ip=source_ip,
                                                      destination_ip=destination_ip,
                                                      dscp=dscp,
                                                      timeout=timeout)

    def get_pmtu_discovery_status(self, operation_id, timeout=30):
        return self.local_client.get_pmtu_discovery_status(operation_id=operation_id, timeout=timeout)

    def get_external_interfaces_of_pmtu_discovery(self, timeout=30):
        return self.local_client.get_external_interfaces_of_pmtu_discovery(timeout=timeout)

    def get_ip_security_associations(self, policy_id, tnl_pod_hostname, timeout=30):
        return self.local_client.get_ip_security_associations(policy_id=policy_id,
                                                              tnl_pod_hostname=tnl_pod_hostname,
                                                              timeout=timeout)

    def start_ip_reachability_test(self, timeout=30):
        return self.local_client.start_ip_reachability_test(timeout=timeout)

    def get_ip_reachability_test_status(self, operation_id, timeout=30):
        return self.local_client.get_ip_reachability_test_status(operation_id=operation_id, timeout=timeout)
